INSERT INTO catalog_import (ref, name, merge_into, tracking, primary_muscle, secondary_muscles,
                            equipment, requires, difficulty, instructions, instructions_pl,
                            image, gif)
VALUES
    ('gymvisual:0001', '3/4 Sit-Up', NULL, 'reps', 'abs', ARRAY['quadriceps', 'lower_back']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie flat on your back with your knees bent and feet flat on the ground.
Place your hands behind your head with your elbows pointing outwards.
Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.
Umieść dłonie za głową, kierując łokcie na zewnątrz.
Angażując mięśnie brzucha, powoli unieś górną część ciała nad podłogę, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0001-2gPfomN.jpg', 'videos/0001-2gPfomN.gif'),
    ('gymvisual:0002', '45° Side Bend', NULL, 'reps', 'abs', ARRAY[]::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Stand with your feet shoulder-width apart and your arms extended straight down by your sides.
Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.
Pause for a moment at the bottom, then slowly return to the starting position.
Repeat on the other side.
Continue alternating sides for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, ramiona wyprostowane wzdłuż tułowia.
Utrzymując proste plecy i napięty brzuch, powoli pochyl tułów w bok, opuszczając dłoń w kierunku kolana.
Zatrzymaj się na chwilę w dolnej pozycji, a następnie powoli wróć do pozycji wyjściowej.
Powtórz po drugiej stronie.
Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń.', 'images/0002-Hy9D21L.jpg', 'videos/0002-Hy9D21L.gif'),
    ('gymvisual:0003', 'Air Bike', NULL, 'reps', 'abs', ARRAY['quadriceps']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie flat on your back with your hands placed behind your head.
Lift your legs off the ground and bend your knees at a 90-degree angle.
Bring your right elbow towards your left knee while simultaneously straightening your right leg.
Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.
Continue alternating sides in a pedaling motion for the desired number of repetitions.', 'Połóż się płasko na plecach, dłonie umieść za głową.
Unieś nogi nad podłogę i ugnij kolana pod kątem 90 stopni.
Przyciągnij prawy łokieć w kierunku lewego kolana, jednocześnie prostując prawą nogę.
Wróć do pozycji wyjściowej i powtórz ruch po przeciwnej stronie, przyciągając lewy łokieć do prawego kolana i prostując lewą nogę.
Kontynuuj naprzemienny ruch przypominający pedałowanie przez zalecaną liczbę powtórzeń.', 'images/0003-1ZFqTDN.jpg', 'videos/0003-1ZFqTDN.gif'),
    ('gymvisual:0006', 'Alternate Heel Touchers', NULL, 'reps', 'abs', ARRAY[]::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie flat on your back with your knees bent and feet flat on the ground.
Extend your arms straight out to the sides, parallel to the ground.
Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.
Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.
Continue alternating sides for the desired number of repetitions.', 'Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.
Wyciągnij ramiona na boki, równolegle do podłogi.
Angażując mięśnie brzucha, unieś barki nad podłogę i sięgnij prawą dłonią w kierunku prawej pięty.
Wróć do pozycji wyjściowej i powtórz po lewej stronie, sięgając lewą dłonią do lewej pięty.
Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń.', 'images/0006-qaZVsGk.jpg', 'videos/0006-qaZVsGk.gif'),
    ('gymvisual:0007', 'Alternate Lateral Pulldown', NULL, 'weight_reps', 'lats', ARRAY['biceps', 'upper_back']::TEXT[], 'cable', ARRAY['lat_pulldown']::TEXT[], 'beginner', 'Sit on the cable machine with your back straight and feet flat on the ground.
Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.
Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na maszynie linkowej z prostymi plecami i stopami płasko na podłodze.
Chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.
Odchyl się lekko do tyłu i przyciągnij uchwyty w kierunku klatki piersiowej, ściskając łopatki.
Zatrzymaj się na chwilę w szczytowej fazie ruchu, a następnie powoli uwolnij uchwyty do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0007-4IKbhHV.jpg', 'videos/0007-4IKbhHV.gif'),
    ('gymvisual:0009', 'Assisted Chest Dip (Kneeling)', NULL, 'weight_reps', 'chest', ARRAY['triceps', 'shoulders']::TEXT[], 'machine', ARRAY['assisted_pull_up_machine']::TEXT[], 'beginner', 'Adjust the machine to your desired height and secure your knees on the pad.
Grasp the handles with your palms facing down and your arms fully extended.
Lower your body by bending your elbows until your upper arms are parallel to the floor.
Pause for a moment, then push yourself back up to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw maszynę na odpowiednią wysokość i oprzyj kolana na poduszce.
Chwyć uchwyty dłońmi skierowanymi w dół, ramiona w pełni wyprostowane.
Opuść ciało, uginając łokcie, aż ramiona będą równoległe do podłogi.
Zatrzymaj się na chwilę, a następnie wypchnij się z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0009-PAgTVaK.jpg', 'videos/0009-PAgTVaK.gif'),
    ('gymvisual:0010', 'Assisted Hanging Knee Raise with Throw Down', NULL, 'reps', 'abs', ARRAY['quadriceps', 'lower_back']::TEXT[], 'none', ARRAY['pull_up_bar']::TEXT[], 'beginner', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
Engage your core and lift your knees towards your chest, keeping your legs together.
Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.
Allow your legs to swing back up and repeat the movement for the desired number of repetitions.', 'Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i dłońmi skierowanymi od siebie.
Napnij mięśnie brzucha i unieś kolana w kierunku klatki piersiowej, trzymając nogi razem.
Gdy kolana znajdą się na wysokości klatki piersiowej, gwałtownie wyrzuć nogi w dół, w pełni je prostując.
Pozwól nogom wrócić w górę wahadłowym ruchem i powtórz zalecaną liczbę razy.', 'images/0010-8K0w2yA.jpg', 'videos/0010-8K0w2yA.gif'),
    ('gymvisual:0011', 'Assisted Hanging Knee Raise', NULL, 'reps', 'abs', ARRAY['quadriceps']::TEXT[], 'none', ARRAY['pull_up_bar']::TEXT[], 'beginner', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.
Pause for a moment at the top of the movement, squeezing your abs.
Slowly lower your legs back down to the starting position.
Repeat for the desired number of repetitions.', 'Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i dłońmi skierowanymi od siebie.
Napnij mięśnie brzucha i unieś kolana w kierunku klatki piersiowej, uginając biodra i kolana.
Zatrzymaj się na chwilę w górnej fazie ruchu, ściskając mięśnie brzucha.
Powoli opuść nogi z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0011-03lzqwk.jpg', 'videos/0011-03lzqwk.gif'),
    ('gymvisual:0012', 'Assisted Lying Leg Raise with Lateral Throw Down', NULL, 'reps', 'abs', ARRAY['quadriceps']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie flat on your back with your legs extended and your arms by your sides.
Place your hands under your glutes for support.
Engage your abs and lift your legs off the ground, keeping them straight.
While keeping your legs together, lower them to one side until they are a few inches above the ground.
Pause for a moment, then lift your legs back to the starting position.
Repeat the movement to the other side.
Continue alternating sides for the desired number of repetitions.', 'Połóż się płasko na plecach z wyciągniętymi nogami i ramionami wzdłuż tułowia.
Umieść dłonie pod pośladkami dla wsparcia.
Napnij mięśnie brzucha i unieś nogi nad podłogę, utrzymując je proste.
Trzymając nogi razem, opuść je na bok, aż znajdą się kilka centymetrów nad podłogą.
Zatrzymaj się na chwilę, a następnie unieś nogi z powrotem do pozycji wyjściowej.
Powtórz ruch po drugiej stronie.
Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń.', 'images/0012-UGhRD1A.jpg', 'videos/0012-UGhRD1A.gif'),
    ('gymvisual:0013', 'Assisted Lying Leg Raise with Throw Down', NULL, 'reps', 'abs', ARRAY['quadriceps']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie flat on your back with your legs extended and your arms by your sides.
Place your hands under your glutes for support.
Engage your core and lift your legs off the ground, keeping them straight.
Raise your legs until they are perpendicular to the ground.
Lower your legs back down to the starting position.
Simultaneously, throw your legs down towards the ground, keeping them straight.
Raise your legs back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na plecach z wyciągniętymi nogami i ramionami wzdłuż tułowia.
Umieść dłonie pod pośladkami dla wsparcia.
Napnij mięśnie brzucha i unieś nogi nad podłogę, utrzymując je proste.
Unieś nogi, aż będą prostopadłe do podłogi.
Opuść nogi z powrotem do pozycji wyjściowej.
Jednocześnie wyrzuć nogi w dół w kierunku podłogi, utrzymując je proste.
Unieś nogi z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0013-VX5YKR5.jpg', 'videos/0013-VX5YKR5.gif'),
    ('gymvisual:0014', 'Assisted Motion Russian Twist', NULL, 'weight_reps', 'abs', ARRAY['lower_back']::TEXT[], 'other', ARRAY['medicine_ball']::TEXT[], 'beginner', 'Sit on the ground with your knees bent and feet flat on the floor.
Hold the medicine ball with both hands in front of your chest.
Lean back slightly, engaging your abs and keeping your back straight.
Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.
Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.
Continue alternating sides for the desired number of repetitions.', 'Usiądź na podłodze z ugiętymi kolanami i stopami płasko na podłodze.
Trzymaj piłkę lekarską obiema rękami przed klatką piersiową.
Odchyl się lekko do tyłu, napinając mięśnie brzucha i utrzymując proste plecy.
Powoli skręć tułów w prawo, przenosząc piłkę lekarską w kierunku prawej strony ciała.
Zatrzymaj się na chwilę, a następnie skręć tułów w lewo, przenosząc piłkę lekarską w kierunku lewej strony ciała.
Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń.', 'images/0014-r7cT9YD.jpg', 'videos/0014-r7cT9YD.gif'),
    ('gymvisual:0015', 'Assisted Parallel Close Grip Pull-Up', NULL, 'weight_reps', 'lats', ARRAY['biceps', 'forearms']::TEXT[], 'machine', ARRAY['assisted_pull_up_machine']::TEXT[], 'beginner', 'Adjust the machine to your desired weight and height.
Place your hands on the parallel bars with a close grip, palms facing each other.
Hang from the bars with your arms fully extended and your feet off the ground.
Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.
Continue pulling until your chin is above the bars.
Pause for a moment at the top, then slowly lower your body back down to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw maszynę na odpowiedni ciężar i wysokość.
Umieść dłonie na równoległych poręczach wąskim chwytem, dłońmi zwróconymi do siebie.
Zwiśnij na poręczach z rękami w pełni wyprostowanymi i stopami uniesionymi nad podłogę.
Napnij mięśnie pleców i podciągnij ciało w kierunku poręczy, trzymając łokcie blisko ciała.
Kontynuuj podciąganie, aż broda znajdzie się nad poręczami.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0015-vrhHa6D.jpg', 'videos/0015-vrhHa6D.gif'),
    ('gymvisual:0016', 'Assisted Prone Hamstring', NULL, 'reps', 'hamstrings', ARRAY['glutes', 'lower_back']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Lie face down on a mat or bench with your legs fully extended.
Have a partner or use a resistance band to secure your ankles.
Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.
Pause for a moment at the top, then slowly lower your legs back down to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się na brzuchu na macie lub ławce z nogami w pełni wyprostowanymi.
Poproś partnera lub użyj taśmy oporowej, aby zabezpieczyć kostki.
Napnij mięśnie dwugłowe uda i unieś nogi w kierunku pośladków, utrzymując proste kolana.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0016-VedGSby.jpg', 'videos/0016-VedGSby.gif'),
    ('gymvisual:0017', 'Assisted Pull-Up', NULL, 'weight_reps', 'lats', ARRAY['biceps', 'forearms']::TEXT[], 'machine', ARRAY['assisted_pull_up_machine']::TEXT[], 'beginner', 'Adjust the machine to your desired weight and height settings.
Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
Hang with your arms fully extended and your feet off the ground.
Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.
Continue pulling until your chin is above the handles.
Pause for a moment at the top, then slowly lower your body back down to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw maszynę na odpowiedni ciężar i wysokość.
Chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.
Zwiśnij z rękami w pełni wyprostowanymi i stopami uniesionymi nad podłogę.
Napnij mięśnie pleców i podciągnij ciało w kierunku uchwytów, trzymając łokcie blisko ciała.
Kontynuuj podciąganie, aż broda znajdzie się nad uchwytami.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0017-kiJ4Z2K.jpg', 'videos/0017-kiJ4Z2K.gif'),
    ('gymvisual:0018', 'Assisted Standing Triceps Extension (with Towel)', NULL, 'reps', 'triceps', ARRAY['shoulders']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.
Keep your elbows close to your ears and your upper arms stationary.
Slowly extend your forearms upward, squeezing your triceps at the top.
Pause for a moment, then slowly lower the towel back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków i trzymaj ręcznik obiema rękami za głową.
Trzymaj łokcie blisko uszu, a ramiona nieruchome.
Powoli prostuj przedramiona w górę, ściskając triceps w górnej fazie ruchu.
Zatrzymaj się na chwilę, a następnie powoli opuść ręcznik z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0018-7HcfMBP.jpg', 'videos/0018-7HcfMBP.gif'),
    ('gymvisual:0019', 'Assisted Triceps Dip (Kneeling)', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'machine', ARRAY['assisted_pull_up_machine']::TEXT[], 'beginner', 'Adjust the machine to your desired weight and height.
Kneel down on the pad facing the machine, with your hands gripping the handles.
Lower your body by bending your elbows, keeping your back straight and close to the machine.
Pause for a moment at the bottom, then push yourself back up to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw maszynę na odpowiedni ciężar i wysokość.
Uklęknij na poduszce przodem do maszyny, trzymając uchwyty dłońmi.
Opuść ciało, uginając łokcie, utrzymując proste plecy blisko maszyny.
Zatrzymaj się na chwilę w dolnej pozycji, a następnie wypchnij się z powrotem do pozycji wyjściowej.
Powtórz zalecaną liczbę razy.', 'images/0019-J60bN17.jpg', 'videos/0019-J60bN17.gif'),
    ('gymvisual:0020', 'Balance Board', NULL, 'reps', 'quadriceps', ARRAY['calves', 'hamstrings', 'glutes']::TEXT[], 'none', ARRAY[]::TEXT[], 'beginner', 'Place the balance board on a flat surface.
Step onto the balance board with one foot, ensuring it is centered.
Slowly shift your weight onto the foot on the balance board, keeping your core engaged.
Maintain your balance and stability as you hold the position for a desired amount of time.
Repeat the exercise with the other foot.', 'Umieść deskę równoważną na płaskiej powierzchni.
Wejdź na deskę jedną stopą, upewniając się, że jest wyśrodkowana.
Powoli przenieś ciężar ciała na stopę stojącą na desce, napinając mięśnie brzucha.
Utrzymuj równowagę i stabilność, trzymając pozycję przez zalecany czas.
Powtórz ćwiczenie drugą stopą.', 'images/0020-xAySMB0.jpg', 'videos/0020-xAySMB0.gif'),
    ('gymvisual:0022', 'Barbell Pullover to Press', NULL, 'weight_reps', 'lats', ARRAY['triceps', 'chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Lie flat on a bench with your head at one end and your feet on the ground.
Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.
Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.
Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, głową na jednym końcu, a stopy oprzyj na podłodze.
Chwyć sztangę chwytem pronowanym (dłonie skierowane od siebie) i wyprostuj ręce nad klatką piersiową.
Utrzymując ręce proste, opuszczaj sztangę za głowę ruchem łukowym, aż poczujesz rozciąganie mięśni najszerszych grzbietu.
Zatrzymaj się na chwilę, a następnie wykonaj ruch odwrotny, wypychając sztangę z powrotem do pozycji wyjściowej nad klatką piersiową.
Powtórz odpowiednią liczbę razy.', 'images/0022-znLogoF.jpg', 'videos/0022-znLogoF.gif'),
    ('gymvisual:0023', 'Barbell Alternate Biceps Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.
Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.
Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale as you slowly begin to lower the barbells back to the starting position.
Repeat for the desired number of repetitions, alternating arms.', 'Stań prosto, stopy rozstaw na szerokość barków i chwyć sztangielkę w każdą rękę, dłonie skierowane do przodu.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.
Unoś sztangielki, aż biceps będzie w pełni napięty, a sztangielki znajdą się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangielki do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy, na przemian dla obu rąk.', 'images/0023-Yza7XrQ.jpg', 'videos/0023-Yza7XrQ.gif'),
    ('gymvisual:0024', 'Barbell Bench Front Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['hamstrings', 'glutes', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.
Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.
Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.
Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, opierając sztangę na górnej części klatki piersiowej, tuż poniżej obojczyka.
Trzymaj sztangę chwytem nachwytem, utrzymując łokcie uniesione, a ramiona równoległe do podłoża.
Opuść ciało do pozycji przysiadu, zginając kolana i biodra, utrzymując proste plecy i uniesioną klatkę piersiową.
Zatrzymaj się na chwilę w dolnej fazie przysiadu, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0024-Y7YcmIJ.jpg', 'videos/0024-Y7YcmIJ.gif'),
    ('gymvisual:0025', 'Barbell Bench Press', 'Barbell Bench Press', 'weight_reps', 'chest', ARRAY['triceps', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
Lower the barbell slowly towards your chest, keeping your elbows tucked in.
Pause for a moment when the barbell touches your chest.
Push the barbell back up to the starting position by extending your arms.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.
Chwyć sztangę chwytem nachwytem nieco szerszym niż szerokość barków.
Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.
Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.
Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.
Wypchnij sztangę z powrotem do pozycji wyjściowej, prostując ręce.
Powtórz odpowiednią liczbę razy.', 'images/0025-EIeI8Vf.jpg', 'videos/0025-EIeI8Vf.gif'),
    ('gymvisual:0026', 'Barbell Bench Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Set up a barbell on a squat rack at chest height.
Stand facing away from the rack, with your feet shoulder-width apart.
Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.
Lower your body down into a squat, keeping your knees in line with your toes.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw sztangę na stojaku na wysokości klatki piersiowej.
Stań tyłem do stojaka, stopy rozstaw na szerokość barków.
Ugnij kolana i opuść ciało do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Zdejmij sztangę ze stojaka i zrób krok w tył, upewniając się, że stopy nadal są rozstawione na szerokość barków.
Opuść ciało do pozycji przysiadu, utrzymując kolana w linii ze stopami.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0026-W9pFVv1.jpg', 'videos/0026-W9pFVv1.gif'),
    ('gymvisual:0027', 'Barbell Row', 'Barbell Row', 'weight_reps', 'upper_back', ARRAY['biceps', 'forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and knees slightly bent.
Bend forward at the hips while keeping your back straight and chest up.
Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.
Pause for a moment at the top, then slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, kolana lekko ugięte.
Pochyl tułów w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.
Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Przyciągnij sztangę w kierunku dolnej części klatki piersiowej, ściągając łopatki i napinając mięśnie grzbietu.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0027-eZyBC3j.jpg', 'videos/0027-eZyBC3j.gif'),
    ('gymvisual:0028', 'Barbell Clean and Press', NULL, 'weight_reps', 'quadriceps', ARRAY['hamstrings', 'glutes', 'shoulders', 'triceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'advanced', 'Stand with your feet shoulder-width apart and the barbell on the floor in front of you.
Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.
As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.
As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.
From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.
Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, ze sztangą leżącą na podłodze przed tobą.
Ugnij kolana i pochyl się w biodrach, aby chwycić sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Odepchnij się od podłoża piętami i wyprostuj biodra i kolana, unosząc sztangę z podłogi blisko ciała.
Gdy sztanga osiągnie wysokość ud, dynamicznie wyprostuj biodra, unieś barki i przyciągnij sztangę w górę w kierunku klatki piersiowej.
Gdy sztanga osiągnie wysokość klatki piersiowej, szybko zejdź pod nią i złap ją na wysokości barków, z łokciami skierowanymi do przodu i dłońmi skierowanymi do góry.
Z pozycji podchwytu wypchnij sztangę nad głowę, prostując ręce i pchając sztangę prosto w górę.
Opuść sztangę z powrotem do pozycji wyjściowej i powtórz odpowiednią liczbę razy.', 'images/0028-SGY8Zui.jpg', 'videos/0028-SGY8Zui.gif'),
    ('gymvisual:0029', 'Barbell Clean-Grip Front Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves', 'abs']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.
Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.
Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.
Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, opierając sztangę na górnej części klatki piersiowej, z łokciami skierowanymi do przodu.
Opuść ciało, uginając kolana i cofając biodra, jakbyś siadał na krześle.
Utrzymuj uniesioną klatkę piersiową i proste plecy podczas opuszczania, upewniając się, że kolana nie wychodzą poza linię palców stóp.
Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.
Powtórz odpowiednią liczbę razy.', 'images/0029-qi996YS.jpg', 'videos/0029-qi996YS.gif'),
    ('gymvisual:0030', 'Close-Grip Bench Press', 'Close-Grip Bench Press', 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.
Pause for a moment when the barbell touches your chest.
Push the barbell back up to the starting position, fully extending your arms.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.
Chwyć sztangę wąskim chwytem, nieco węższym niż szerokość barków.
Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie blisko ciała.
Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.
Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.
Powtórz odpowiednią liczbę razy.', 'images/0030-J6Dx1Mu.jpg', 'videos/0030-J6Dx1Mu.gif'),
    ('gymvisual:0031', 'Barbell Curl', 'Barbell Curl', 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.
Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.
Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale as you slowly begin to lower the bar back to the starting position.
Repeat for the desired number of repetitions.', 'Stań prosto, stopy rozstaw na szerokość barków, i chwyć sztangę chwytem podchwytem, dłonie skierowane do przodu.
Trzymaj łokcie blisko tułowia i wydychaj powietrze, uginając ręce i napinając biceps.
Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0031-25GPyDY.jpg', 'videos/0031-25GPyDY.gif'),
    ('gymvisual:0032', 'Conventional Deadlift', 'Conventional Deadlift', 'weight_reps', 'glutes', ARRAY['hamstrings', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and the barbell on the ground in front of you.
Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.
As you stand up straight, squeeze your glutes and keep your core engaged.
Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, ze sztangą leżącą na podłodze przed tobą.
Ugnij kolana i pochyl się w biodrach, aby opuścić tułów i chwycić sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Utrzymując proste plecy i uniesioną klatkę piersiową, odepchnij się piętami, unosząc sztangę z podłogi, prostując biodra i kolana.
Gdy staniesz prosto, ściśnij pośladki i utrzymuj napięcie mięśni tułowia.
Opuść sztangę z powrotem na podłogę, uginając biodra i kolana, utrzymując proste plecy.
Powtórz odpowiednią liczbę razy.', 'images/0032-ila4NZS.jpg', 'videos/0032-ila4NZS.gif'),
    ('gymvisual:0033', 'Barbell Decline Bench Press', NULL, 'weight_reps', 'chest', ARRAY['triceps', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench', 'squat_rack']::TEXT[], 'intermediate', 'Lie on a decline bench with your feet secured and your head lower than your hips.
Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
Pause for a moment at the bottom, then push the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się na ławce skośnej ujemnej, zabezpieczając stopy, tak aby głowa znajdowała się niżej niż biodra.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie przy ciele.
Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0033-GrO65fd.jpg', 'videos/0033-GrO65fd.gif'),
    ('gymvisual:0034', 'Barbell Decline Bent Arm Pullover', NULL, 'weight_reps', 'lats', ARRAY['triceps', 'chest']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Lie down on a decline bench with your head lower than your hips and your feet secured.
Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.
Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.
Pause for a moment, then raise the barbell back to the starting position by contracting your lats.
Repeat for the desired number of repetitions.', 'Połóż się na ławce skośnej ujemnej, tak aby głowa znajdowała się niżej niż biodra, a stopy były zabezpieczone.
Chwyć sztangę chwytem pronowanym (dłonie skierowane od siebie) i wyprostuj ręce nad klatką piersiową.
Opuszczaj sztangę za głowę w kontrolowany sposób, utrzymując ręce lekko ugięte.
Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej, napinając mięśnie najszersze grzbietu.
Powtórz odpowiednią liczbę razy.', 'images/0034-hMEptv0.jpg', 'videos/0034-hMEptv0.gif'),
    ('gymvisual:0035', 'Barbell Decline Close Grip to Skull Press', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.
Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.
Pause for a moment, then extend your arms to press the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się na ławce skośnej ujemnej, głową niżej niż stopy, i chwyć sztangę wąskim chwytem.
Opuść sztangę w kierunku czoła, uginając łokcie i utrzymując ramiona nieruchomo.
Zatrzymaj się na chwilę, a następnie wyprostuj ręce, wypychając sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0035-LMGXZn8.jpg', 'videos/0035-LMGXZn8.gif'),
    ('gymvisual:0036', 'Barbell Decline Wide-Grip Press', NULL, 'weight_reps', 'chest', ARRAY['triceps', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Lie on a decline bench with your feet secured and your head lower than your hips.
Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
Lower the barbell to your chest, keeping your elbows out to the sides.
Push the barbell back up to the starting position, fully extending your arms.
Repeat for the desired number of repetitions.', 'Połóż się na ławce skośnej ujemnej, zabezpieczając stopy, tak aby głowa znajdowała się niżej niż biodra.
Chwyć sztangę szerokim chwytem, nieco szerszym niż szerokość barków.
Opuść sztangę do klatki piersiowej, trzymając łokcie skierowane na boki.
Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.
Powtórz odpowiednią liczbę razy.', 'images/0036-hl8DUh8.jpg', 'videos/0036-hl8DUh8.gif'),
    ('gymvisual:0037', 'Barbell Decline Wide-Grip Pullover', NULL, 'weight_reps', 'lats', ARRAY['triceps', 'chest']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Lie on a decline bench with your head lower than your hips and your feet secured.
Hold a barbell with a wide grip and extend your arms straight above your chest.
Lower the barbell behind your head in a controlled manner, keeping your arms straight.
Pause for a moment, then raise the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się na ławce skośnej ujemnej, tak aby głowa znajdowała się niżej niż biodra, a stopy były zabezpieczone.
Chwyć sztangę szerokim chwytem i wyprostuj ręce nad klatką piersiową.
Opuszczaj sztangę za głowę w kontrolowany sposób, utrzymując ręce proste.
Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0037-Hj4FOCd.jpg', 'videos/0037-Hj4FOCd.gif'),
    ('gymvisual:0038', 'Barbell Drag Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.
Let the barbell hang at arm''s length in front of your thighs.
Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków i chwyć sztangę chwytem podchwytem, dłonie skierowane do góry.
Trzymaj sztangę swobodnie opuszczoną na wyciągniętych ramionach przed udami.
Utrzymując ramiona nieruchomo, uginaj sztangę w kierunku klatki piersiowej, napinając biceps.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0038-IENzBdA.jpg', 'videos/0038-IENzBdA.gif'),
    ('gymvisual:0039', 'Barbell Front Chest Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves', 'abs']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart, toes slightly turned out.
Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.
Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.
Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.
Trzymaj sztangę przed klatką piersiową, dłonie na szerokość barków, łokcie skierowane do przodu.
Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, opuszczając ciało do pozycji przysiadu, cofając biodra i uginając kolana.
Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0039-IeTIEqg.jpg', 'videos/0039-IeTIEqg.gif'),
    ('gymvisual:0040', 'Barbell Front Raise and Pullover', NULL, 'weight_reps', 'chest', ARRAY['shoulders', 'triceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
Next, lower the barbell behind your head, keeping your arms straight.
Pause for a moment at the bottom, then raise the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.
Utrzymując ręce proste, unieś sztangę przed sobą, aż osiągnie wysokość barków.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Następnie opuść sztangę za głowę, utrzymując ręce proste.
Zatrzymaj się na chwilę na dole, a następnie unieś sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0040-33AzZeV.jpg', 'videos/0040-33AzZeV.gif'),
    ('gymvisual:0041', 'Barbell Front Raise', NULL, 'weight_reps', 'shoulders', ARRAY['biceps', 'triceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.
Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków i chwyć sztangę przed udami chwytem nachwytem.
Utrzymując ręce proste, unieś sztangę do przodu i w górę, aż osiągnie wysokość barków.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0041-b2Uoz54.jpg', 'videos/0041-b2Uoz54.gif'),
    ('gymvisual:0042', 'Front Squat', 'Front Squat', 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves', 'abs']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart, toes slightly turned out.
Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.
Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.
Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.
Trzymaj sztangę przed barkami, opierając ją na obojczyku i barkach.
Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, opuszczając ciało do pozycji przysiadu, cofając biodra i uginając kolana.
Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0042-zG0zs85.jpg', 'videos/0042-zG0zs85.gif'),
    ('gymvisual:0043', 'Barbell Back Squat', 'Barbell Back Squat', 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves', 'abs']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, toes slightly turned out.
Hold the barbell across your upper back, resting it on your traps or rear delts.
Engage your core and keep your chest up as you begin to lower your body down.
Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.
Lower yourself until your thighs are parallel to the ground or slightly below.
Keep your knees in line with your toes and your weight in your heels.
Drive through your heels to stand back up, extending your hips and knees.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.
Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.
Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, rozpoczynając opuszczanie ciała.
Ugnij kolana i biodra, cofając biodra w dół, jakbyś siadał na krześle.
Opuszczaj się, aż uda będą równoległe do podłoża lub nieco niżej.
Utrzymuj kolana w linii ze stopami, a ciężar ciała w piętach.
Wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.
Powtórz odpowiednią liczbę razy.', 'images/0043-qXTaZnJ.jpg', 'videos/0043-qXTaZnJ.gif'),
    ('gymvisual:0044', 'Barbell Good Morning', NULL, 'weight_reps', 'hamstrings', ARRAY['lower_back']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.
Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.
Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.
Utrzymując proste plecy i napięte mięśnie tułowia, pochyl się w biodrach, cofając pośladki, jakbyś próbował dotknąć nimi ściany za sobą.
Opuszczaj tułów, aż będzie równoległy do podłoża, odczuwając rozciąganie mięśni dwugłowych uda.
Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej, ściskając pośladki i pchając biodra do przodu.
Powtórz odpowiednią liczbę razy.', 'images/0044-XlZ4lAC.jpg', 'videos/0044-XlZ4lAC.gif'),
    ('gymvisual:0045', 'Barbell Guillotine Bench Press', NULL, 'weight_reps', 'chest', ARRAY['shoulders', 'triceps']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.
Pause for a moment when the barbell is just above your neck.
Push the barbell back up to the starting position, fully extending your arms.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Powoli opuszczaj sztangę w kierunku szyi, trzymając łokcie skierowane na zewnątrz.
Zatrzymaj się na chwilę, gdy sztanga znajdzie się tuż nad szyją.
Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.
Powtórz odpowiednią liczbę razy.', 'images/0045-GXoaSgn.jpg', 'videos/0045-GXoaSgn.gif'),
    ('gymvisual:0046', 'Barbell Hack Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and your toes slightly turned out.
Hold the barbell behind your legs, resting it on your upper thighs.
Lower your body by bending at the knees and hips, keeping your back straight and your chest up.
Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
Pause for a moment, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.
Trzymaj sztangę za nogami, opierając ją na górnej części ud.
Opuść ciało, uginając kolana i biodra, utrzymując proste plecy i uniesioną klatkę piersiową.
Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Zatrzymaj się na chwilę, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0046-5VCj6iH.jpg', 'videos/0046-5VCj6iH.gif'),
    ('gymvisual:0047', 'Barbell Incline Bench Press', NULL, 'weight_reps', 'chest', ARRAY['shoulders', 'triceps']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench', 'squat_rack']::TEXT[], 'intermediate', 'Set up an incline bench at a 45-degree angle.
Lie down on the bench with your feet flat on the ground.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.
Pause for a moment at the bottom, then push the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.
Połóż się na ławce, stopy oprzyj płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, utrzymując łokcie pod kątem 45 stopni.
Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0047-3TZduzM.jpg', 'videos/0047-3TZduzM.gif'),
    ('gymvisual:0048', 'Barbell Incline Reverse-Grip Press', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Set up an incline bench at a 45-degree angle.
Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.
Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.
Pause for a moment at the bottom, then push the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.
Połóż się na ławce i chwyć sztangę chwytem odwrotnym, dłonie nieco szerzej niż szerokość barków.
Zdejmij sztangę ze stojaka i opuszczaj ją w kierunku górnej części klatki piersiowej, trzymając łokcie blisko ciała.
Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0048-641mIfk.jpg', 'videos/0048-641mIfk.gif'),
    ('gymvisual:0049', 'Barbell Incline Row', NULL, 'weight_reps', 'upper_back', ARRAY['biceps', 'forearms']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Set up an incline bench at a 45-degree angle.
Lie face down on the bench with your chest against the pad and your feet flat on the ground.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Keep your back straight and your core engaged.
Pull the barbell towards your chest, squeezing your shoulder blades together.
Pause for a moment at the top, then slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.
Połóż się twarzą w dół na ławce, opierając klatkę piersiową o poduszkę, a stopy ustaw płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Utrzymuj proste plecy i napięte mięśnie tułowia.
Przyciągnij sztangę w kierunku klatki piersiowej, ściskając łopatki.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0049-dmgMp3n.jpg', 'videos/0049-dmgMp3n.gif'),
    ('gymvisual:0050', 'Barbell Incline Shoulder Raise', NULL, 'weight_reps', 'chest', ARRAY['shoulders', 'traps']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Set up an incline bench at a 45-degree angle.
Sit on the bench with your back against the pad and feet flat on the ground.
Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.
Lift the barbell up to shoulder height, keeping your elbows slightly bent.
Slowly raise the barbell overhead, extending your arms fully.
Pause for a moment at the top, then slowly lower the barbell back to shoulder height.
Repeat for the desired number of repetitions.', 'Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.
Usiądź na ławce, opierając plecy o poduszkę, a stopy ustaw płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Unieś sztangę do wysokości barków, utrzymując łokcie lekko ugięte.
Powoli unieś sztangę nad głowę, w pełni prostując ręce.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do wysokości barków.
Powtórz odpowiednią liczbę razy.', 'images/0050-xi0yckC.jpg', 'videos/0050-xi0yckC.gif'),
    ('gymvisual:0051', 'Barbell Jefferson Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and toes slightly turned out.
Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.
Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.
Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.
Push through your heels to stand back up to the starting position.
Repeat the movement, alternating your forward and back foot with each repetition.', 'Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.
Trzymaj sztangę chwytem nachwytem, opierając ją z przodu ciała, tuż poniżej talii.
Zrób krok lewą stopą do przodu, a prawą stopą do tyłu, utrzymując stopy rozstawione na szerokość barków.
Ugnij kolana i opuść ciało do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.
Wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz ruch, zmieniając przednią i tylną stopę przy każdym powtórzeniu.', 'images/0051-pkSoCW9.jpg', 'videos/0051-pkSoCW9.gif'),
    ('gymvisual:0052', 'Barbell JM Bench Press', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lower the barbell to your chest, keeping your elbows tucked in close to your body.
Push the barbell back up to the starting position, fully extending your arms.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Opuść sztangę do klatki piersiowej, trzymając łokcie blisko ciała.
Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.
Powtórz odpowiednią liczbę razy.', 'images/0052-ZsiqXYa.jpg', 'videos/0052-ZsiqXYa.gif'),
    ('gymvisual:0053', 'Barbell Jump Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.
Lower your body into a squat position by bending your knees and pushing your hips back.
Once you reach the bottom of the squat, explode upwards by jumping off the ground.
As you jump, extend your hips, knees, and ankles, pushing through your toes.
Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.
Opuść ciało do pozycji przysiadu, uginając kolana i cofając biodra.
Gdy osiągniesz dolną fazę przysiadu, eksplozywnie wybij się w górę, wyskakując z podłoża.
Podczas wyskoku wyprostuj biodra, kolana i kostki, odpychając się przez palce stóp.
Wyląduj miękko w pozycji przysiadu i natychmiast powtórz ruch odpowiednią liczbę razy.', 'images/0053-1gFNTZV.jpg', 'videos/0053-1gFNTZV.gif'),
    ('gymvisual:0054', 'Barbell Lunge', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.
Take a step forward with your right foot, keeping your torso upright.
Lower your body by bending your right knee until your thigh is parallel to the ground.
Push through your right heel to return to the starting position.
Repeat with your left leg, alternating legs for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.
Zrób krok do przodu prawą stopą, utrzymując tułów wyprostowany.
Opuść ciało, uginając prawe kolano, aż udo będzie równoległe do podłoża.
Odepchnij się przez prawą piętę, wracając do pozycji wyjściowej.
Powtórz lewą nogą, wykonując wykroki naprzemiennie odpowiednią liczbę razy.', 'images/0054-t8iSghb.jpg', 'videos/0054-t8iSghb.gif'),
    ('gymvisual:0055', 'Barbell Lying Close-Grip Press', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.
Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.
Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.
Slowly lower the barbell towards your chest, keeping your elbows close to your body.
Pause for a moment when the barbell touches your chest, then push it back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.
Chwyć sztangę wąskim chwytem, dłonie na szerokość barków, dłonie skierowane w stronę stóp.
Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.
Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.
Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej, a następnie wypchnij ją z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0055-EcaV7aL.jpg', 'videos/0055-EcaV7aL.gif'),
    ('gymvisual:0056', 'Barbell Lying Close-Grip Triceps Extension', NULL, 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.
Extend your arms fully, lifting the barbell above your chest.
Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
Pause for a moment at the bottom, then extend your arms back to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.
Chwyć sztangę wąskim chwytem, dłonie na szerokość barków, dłonie skierowane do góry.
Wyprostuj ręce w pełni, unosząc sztangę nad klatką piersiową.
Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.
Zatrzymaj się na chwilę na dole, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0056-HJ63mSO.jpg', 'videos/0056-HJ63mSO.gif'),
    ('gymvisual:0057', 'Barbell Lying Extension', NULL, 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
Pause for a moment, then extend your arms back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.
Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.
Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.
Zatrzymaj się na chwilę, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0057-EMpUwRI.jpg', 'videos/0057-EMpUwRI.gif'),
    ('gymvisual:0058', 'Barbell Lying Lifting (on Hip)', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'quadriceps']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on your back on a bench with your feet flat on the ground and your knees bent.
Hold the barbell with an overhand grip and position it on your hips.
Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.
Pause for a moment at the top, then slowly lower your hips back down to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na plecach na ławce, stopy oprzyj płasko na podłodze, a kolana ugnij.
Chwyć sztangę chwytem nachwytem i umieść ją na biodrach.
Napinając pośladki, unieś biodra z ławki, aż ciało utworzy prostą linię od kolan do barków.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść biodra z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0058-SNFfUff.jpg', 'videos/0058-SNFfUff.gif'),
    ('gymvisual:0059', 'Barbell Lying Preacher Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell', 'preacher_bench']::TEXT[], 'intermediate', 'Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.
Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale and slowly begin to lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce Scotta, opierając klatkę piersiową o poduszkę, a ręce wyprostuj nad jej krawędzią, trzymając sztangę chwytem podchwytem.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.
Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0059-SYJ4Bkt.jpg', 'videos/0059-SYJ4Bkt.gif'),
    ('gymvisual:0060', 'Skull Crusher', 'Skull Crusher', 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.
Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.
Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.
Zatrzymaj się na chwilę, gdy sztanga znajdzie się tuż nad czołem, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0060-h8LFzo9.jpg', 'videos/0060-h8LFzo9.gif'),
    ('gymvisual:0061', 'Barbell Lying Triceps Extension', NULL, 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.
Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.
Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.
Pause for a moment at the bottom, then extend your arms back up to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.
Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.
Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.
Zatrzymaj się na chwilę na dole, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0061-iZop9xO.jpg', 'videos/0061-iZop9xO.gif'),
    ('gymvisual:0063', 'Barbell Narrow Stance Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and toes pointing slightly outward.
Hold the barbell across your upper back, resting it on your traps or rear delts.
Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.
Continue lowering until your thighs are parallel to the ground or slightly below.
Pause for a moment, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.
Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.
Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, powoli opuszczając ciało, uginając kolana i cofając biodra.
Kontynuuj opuszczanie, aż uda będą równoległe do podłoża lub nieco niżej.
Zatrzymaj się na chwilę, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0063-elhhVgj.jpg', 'videos/0063-elhhVgj.gif'),
    ('gymvisual:0064', 'Barbell One Arm Bent Over Row', NULL, 'weight_reps', 'upper_back', ARRAY['biceps', 'forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.
Bend forward at the hips, keeping your back straight and your head in a neutral position.
Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.
Lower the barbell back down to the starting position in a controlled manner.
Repeat for the desired number of repetitions, then switch to the other arm.', 'Stań w rozkroku na szerokość barków, kolana lekko ugięte, i chwyć sztangę jedną ręką chwytem nachwytem.
Pochyl się do przodu w biodrach, utrzymując proste plecy i głowę w pozycji neutralnej.
Przyciągnij sztangę w kierunku klatki piersiowej, trzymając łokieć blisko ciała i ściskając łopatki.
Opuść sztangę z powrotem do pozycji wyjściowej w kontrolowany sposób.
Powtórz odpowiednią liczbę razy, a następnie zmień rękę.', 'images/0064-Jsgsc27.jpg', 'videos/0064-Jsgsc27.gif'),
    ('gymvisual:0065', 'Barbell One Arm Floor Press', NULL, 'weight_reps', 'triceps', ARRAY['chest', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Lie flat on your back on the floor with your knees bent and feet flat on the ground.
Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.
Slowly lower the barbell towards your chest, keeping your elbow close to your body.
Pause for a moment at the bottom, then push the barbell back up to the starting position.
Repeat for the desired number of repetitions, then switch arms.', 'Połóż się płasko na plecach na podłodze, kolana ugięte, a stopy oparte płasko na podłodze.
Chwyć sztangę jedną ręką, dłonią skierowaną w górę, i wyprostuj rękę nad klatką piersiową.
Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokieć blisko ciała.
Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy, a następnie zmień rękę.', 'images/0065-vtusOWT.jpg', 'videos/0065-vtusOWT.gif'),
    ('gymvisual:0066', 'Barbell One Arm Side Deadlift', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'quadriceps', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.
Keep your back straight and your core engaged.
Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.
Lower the barbell as far as you can while maintaining good form.
Pause for a moment, then slowly return to the starting position.
Repeat for the desired number of repetitions, then switch sides.', 'Stań w rozkroku na szerokość barków, trzymając sztangę jedną ręką chwytem nachwytem.
Utrzymuj proste plecy i napięte mięśnie tułowia.
Pochyl się w biodrach i opuść sztangę wzdłuż zewnętrznej strony nogi, utrzymując rękę prostą, a klatkę piersiową uniesioną.
Opuszczaj sztangę tak nisko, jak pozwala ci na to zachowanie prawidłowej techniki.
Zatrzymaj się na chwilę, a następnie powoli wróć do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy, a następnie zmień stronę.', 'images/0066-2DxtqHL.jpg', 'videos/0066-2DxtqHL.gif'),
    ('gymvisual:0067', 'Barbell One Arm Snatch', NULL, 'weight_reps', 'shoulders', ARRAY['traps', 'forearms', 'abs']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'advanced', 'Stand with your feet shoulder-width apart, toes pointing slightly outwards.
Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.
Explosively extend your hips, knees, and ankles, driving the barbell upwards.
As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.
Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.
Lower the barbell back down to the starting position in a controlled manner.
Repeat for the desired number of repetitions, then switch arms.', 'Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.
Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Ugnij kolana i opuść biodra do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.
Eksplozywnie wyprostuj biodra, kolana i kostki, napędzając sztangę do góry.
Gdy sztanga osiągnie wysokość klatki piersiowej, pociągnij ją w górę ręką, trzymając blisko ciała.
Obróć łokieć pod sztangą i wyprostuj rękę w pełni nad głową, blokując łokieć.
Opuść sztangę z powrotem do pozycji wyjściowej w kontrolowany sposób.
Powtórz odpowiednią liczbę razy, a następnie zmień rękę.', 'images/0067-xHKN2s8.jpg', 'videos/0067-xHKN2s8.gif'),
    ('gymvisual:0068', 'Barbell One Leg Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.
Lift one foot off the ground and extend it forward, keeping it parallel to the ground.
Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.
Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.
Repeat for the desired number of repetitions, then switch legs and repeat.', 'Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.
Unieś jedną stopę z podłogi i wyciągnij ją do przodu, utrzymując równolegle do podłoża.
Ugnij nogę podporową i opuść ciało, jakbyś siadał na krześle, utrzymując uniesioną klatkę piersiową i proste plecy.
Opuszczaj się, aż udo będzie równoległe do podłoża, a następnie odepchnij się przez piętę, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy, a następnie zmień nogę i powtórz.', 'images/0068-uKyN64F.jpg', 'videos/0068-uKyN64F.gif'),
    ('gymvisual:0069', 'Barbell Overhead Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves', 'abs']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and toes slightly turned out.
Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.
Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.
Chwyć sztangę szerokim chwytem, ustawiając ją nad głową przy w pełni wyprostowanych rękach.
Napnij mięśnie tułowia i opuść ciało do pozycji przysiadu, utrzymując uniesioną klatkę piersiową, a kolana w linii ze stopami.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0069-gfk9kD4.jpg', 'videos/0069-gfk9kD4.gif'),
    ('gymvisual:0070', 'Barbell Preacher Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell', 'preacher_bench']::TEXT[], 'intermediate', 'Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.
Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.
Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.
Pause for a moment at the top, squeezing your biceps.
Inhale and slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce Scotta, opierając ramiona na poduszce, a klatkę piersiową o podparcie.
Chwyć sztangę chwytem podchwytem, nieco szerszym niż szerokość barków.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w kierunku barków.
Zatrzymaj się na chwilę na górze, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0070-qOgPVf6.jpg', 'videos/0070-qOgPVf6.gif'),
    ('gymvisual:0071', 'Barbell Press Sit-Up', NULL, 'weight_reps', 'abs', ARRAY['shoulders', 'chest']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Lie flat on your back on a mat with your knees bent and feet flat on the ground.
Hold the barbell with an overhand grip, resting it on your chest.
Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na plecach na macie, kolana ugięte, a stopy oparte płasko na podłodze.
Chwyć sztangę chwytem nachwytem, opierając ją na klatce piersiowej.
Napinając mięśnie brzucha, powoli unieś górną część ciała z podłogi, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0071-wnEscH8.jpg', 'videos/0071-wnEscH8.gif'),
    ('gymvisual:0072', 'Barbell Prone Incline Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell', 'adjustable_bench']::TEXT[], 'intermediate', 'Set up an incline bench at a 45-degree angle.
Lie face down on the bench with your chest and stomach resting against it.
Hold a barbell with an underhand grip, shoulder-width apart.
Extend your arms fully, allowing the barbell to hang down towards the floor.
Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.
Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale and slowly begin to lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.
Połóż się twarzą w dół na ławce, opierając o nią klatkę piersiową i brzuch.
Chwyć sztangę chwytem podchwytem, na szerokość barków.
Wyprostuj ręce w pełni, pozwalając sztandze zwisać w kierunku podłogi.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.
Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0072-WLvTAv5.jpg', 'videos/0072-WLvTAv5.gif'),
    ('gymvisual:0073', 'Barbell Pullover', NULL, 'weight_reps', 'lats', ARRAY['chest', 'triceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Lie flat on a bench with your head at one end and your feet on the floor.
Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.
Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.
Pause for a moment, then raise the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Połóż się płasko na ławce, głową na jednym końcu, a stopy oprzyj na podłodze.
Chwyć sztangę uchwytem na szerokość barków i wyprostuj ręce nad klatką piersiową.
Utrzymując ręce proste, opuszczaj sztangę za głowę w kontrolowany sposób, aż poczujesz rozciąganie mięśni najszerszych grzbietu.
Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0073-i6LWjok.jpg', 'videos/0073-i6LWjok.gif'),
    ('gymvisual:0074', 'Barbell Rack Pull', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Set up a barbell on a rack at knee height.
Stand with your feet shoulder-width apart, toes pointing slightly outwards.
Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.
Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.
Lower the barbell back down to the starting position by bending at the hips and knees.
Repeat for the desired number of repetitions.', 'Ustaw sztangę na stojaku na wysokości kolan.
Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.
Ugnij biodra i kolana, aby opuścić się i chwycić sztangę chwytem nachwytem, dłonie na szerokość barków.
Napnij mięśnie tułowia i unieś sztangę, prostując biodra i kolana, odciągając barki do tyłu i ściskając pośladki na górze.
Opuść sztangę z powrotem do pozycji wyjściowej, uginając biodra i kolana.
Powtórz odpowiednią liczbę razy.', 'images/0074-za9Ni4z.jpg', 'videos/0074-za9Ni4z.gif'),
    ('gymvisual:0075', 'Barbell Rear Delt Raise', NULL, 'weight_reps', 'shoulders', ARRAY['traps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
Bend your knees slightly and hinge forward at the hips, keeping your back straight.
Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.
Pause for a moment at the top, then slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.
Ugnij lekko kolana i pochyl się do przodu w biodrach, utrzymując proste plecy.
Unieś sztangę na boki, utrzymując ręce proste, aż będą równoległe do podłoża.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0075-Ln9iTbU.jpg', 'videos/0075-Ln9iTbU.gif'),
    ('gymvisual:0076', 'Barbell Rear Delt Row', NULL, 'weight_reps', 'shoulders', ARRAY['traps', 'upper_back', 'biceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and knees slightly bent.
Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Bend forward at the hips, keeping your back straight and chest up.
Pull the barbell towards your chest, squeezing your shoulder blades together.
Pause for a moment at the top, then slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, kolana lekko ugięte.
Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.
Przyciągnij sztangę w kierunku klatki piersiowej, ściskając łopatki.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0076-S9zHIvU.jpg', 'videos/0076-S9zHIvU.gif'),
    ('gymvisual:0077', 'Barbell Rear Lunge v. 2', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.
Take a step backward with your right foot, landing on the ball of your foot.
Bend both knees to lower your body until your left thigh is parallel to the ground.
Push through your left heel to return to the starting position.
Repeat with the other leg.', 'Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.
Zrób krok w tył prawą stopą, lądując na palcach stopy.
Ugnij oba kolana, opuszczając ciało, aż lewe udo będzie równoległe do podłoża.
Odepchnij się przez lewą piętę, wracając do pozycji wyjściowej.
Powtórz drugą nogą.', 'images/0077-62Nw60O.jpg', 'videos/0077-62Nw60O.gif'),
    ('gymvisual:0078', 'Barbell Rear Lunge', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.
Take a step backward with your right foot, landing on the ball of your foot.
Bend both knees to lower your body until your left thigh is parallel to the ground.
Push through your left heel to return to the starting position.
Repeat with the other leg.', 'Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.
Zrób krok w tył prawą stopą, lądując na palcach stopy.
Ugnij oba kolana, opuszczając ciało, aż lewe udo będzie równoległe do podłoża.
Odepchnij się przez lewą piętę, wracając do pozycji wyjściowej.
Powtórz drugą nogą.', 'images/0078-VaP75jl.jpg', 'videos/0078-VaP75jl.gif'),
    ('gymvisual:0079', 'Barbell Revers Wrist Curl v. 2', NULL, 'weight_reps', 'forearms', ARRAY['biceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Sit on a bench with your feet flat on the ground and your knees bent.
Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.
Rest your forearms on your thighs, allowing your wrists to hang off the edge.
Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.
Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, stopy oprzyj płasko na podłodze, a kolana ugnij.
Chwyć sztangę chwytem nachwytem, dłonie skierowane w dół, na szerokość barków.
Oprzyj przedramiona na udach, pozwalając nadgarstkom zwisać za krawędzią.
Utrzymując przedramiona nieruchomo, wydychaj powietrze i zginaj nadgarstki w górę, jak najdalej to możliwe.
Zatrzymaj się na chwilę w pozycji szczytowej, a następnie wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0079-qDnGfDb.jpg', 'videos/0079-qDnGfDb.gif'),
    ('gymvisual:0080', 'Barbell Reverse Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.
Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.
Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.
Repeat for the desired number of repetitions.', 'Stań prosto, stopy rozstaw na szerokość barków, i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w górę i napinając biceps.
Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej, utrzymując ramiona nieruchomo.
Powtórz odpowiednią liczbę razy.', 'images/0080-xNrS20v.jpg', 'videos/0080-xNrS20v.gif'),
    ('gymvisual:0081', 'Barbell Reverse Preacher Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell', 'preacher_bench']::TEXT[], 'intermediate', 'Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.
Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.
Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale and slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce Scotta, opierając klatkę piersiową o poduszkę, a ręce wyprostuj prosto w dół, trzymając sztangę chwytem nachwytem.
Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w górę i napinając biceps.
Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.
Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.
Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0081-4LIG9xr.jpg', 'videos/0081-4LIG9xr.gif'),
    ('gymvisual:0082', 'Barbell Reverse Wrist Curl', NULL, 'weight_reps', 'forearms', ARRAY['biceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.
Rest your forearms on your thighs, allowing your wrists to hang off the edge.
Slowly curl your wrists upward, bringing the barbell towards your body.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, stopy oprzyj płasko na podłodze, i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.
Oprzyj przedramiona na udach, pozwalając nadgarstkom zwisać za krawędzią.
Powoli zginaj nadgarstki w górę, przyciągając sztangę w kierunku ciała.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0082-LsZkfU6.jpg', 'videos/0082-LsZkfU6.gif'),
    ('gymvisual:0083', 'Barbell Rollerout from Bench', NULL, 'weight_reps', 'abs', ARRAY['shoulders', 'triceps']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Start by kneeling on the floor with a barbell placed on a bench in front of you.
Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.
Continue rolling the barbell forward until your body is fully extended and your arms are overhead.
Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.
Repeat for the desired number of repetitions.', 'Uklęknij na podłodze ze sztangą umieszczoną na ławce przed sobą.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Utrzymując napięte mięśnie tułowia i proste plecy, powoli tocz sztangę do przodu, wyciągając ręce przed siebie.
Kontynuuj toczenie sztangi do przodu, aż ciało będzie w pełni wyprostowane, a ręce nad głową.
Zatrzymaj się na chwilę w pozycji pełnego wyprostu, a następnie powoli tocz sztangę z powrotem w kierunku ciała, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0083-Gxg9lDc.jpg', 'videos/0083-Gxg9lDc.gif'),
    ('gymvisual:0084', 'Barbell Rollerout', NULL, 'weight_reps', 'abs', ARRAY['lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Kneel on the floor and hold a barbell with both hands, shoulder-width apart.
Roll the barbell forward, extending your arms and keeping your core engaged.
Continue rolling forward until your body is fully extended and your arms are overhead.
Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.
Repeat for the desired number of repetitions.', 'Uklęknij na podłodze i chwyć sztangę oburącz, na szerokość barków.
Toczy sztangę do przodu, prostując ręce i napinając mięśnie tułowia.
Kontynuuj toczenie do przodu, aż ciało będzie w pełni wyprostowane, a ręce nad głową.
Zatrzymaj się na chwilę, a następnie powoli tocz sztangę z powrotem w kierunku kolan, zachowując kontrolę.
Powtórz odpowiednią liczbę razy.', 'images/0084-7M66AVi.jpg', 'videos/0084-7M66AVi.gif'),
    ('gymvisual:0085', 'Romanian Deadlift', 'Romanian Deadlift', 'weight_reps', 'glutes', ARRAY['hamstrings', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and your toes pointing forward.
Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Bend at the hips, keeping your back straight and your knees slightly bent.
Lower the barbell towards the ground, keeping it close to your body.
Feel the stretch in your hamstrings as you lower the barbell.
Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.
Squeeze your glutes at the top of the movement.
Lower the barbell back down to the starting position and repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, palce stóp skierowane do przodu.
Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.
Pochyl się w biodrach, utrzymując proste plecy i lekko ugięte kolana.
Opuszczaj sztangę w kierunku podłogi, trzymając ją blisko ciała.
Poczuj rozciąganie mięśni dwugłowych uda podczas opuszczania sztangi.
Gdy poczujesz rozciąganie w tych mięśniach, wypchnij biodra do przodu i wyprostuj się.
Ściśnij pośladki na szczycie ruchu.
Opuść sztangę z powrotem do pozycji wyjściowej i powtórz odpowiednią liczbę razy.', 'images/0085-wQ2c4XD.jpg', 'videos/0085-wQ2c4XD.gif'),
    ('gymvisual:0086', 'Barbell Seated Behind Head Military Press', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your back straight and feet flat on the ground.
Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lift the barbell off the rack and bring it down to shoulder level, behind your head.
Press the barbell upward until your arms are fully extended.
Lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, plecy wyprostuj, a stopy oprzyj płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Zdejmij sztangę ze stojaka i opuść ją do wysokości barków, za głową.
Wyciśnij sztangę w górę, aż ręce będą w pełni wyprostowane.
Opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0086-ngPpyRS.jpg', 'videos/0086-ngPpyRS.gif'),
    ('gymvisual:0087', 'Barbell Seated Bradford Rocky Press', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your back straight and feet flat on the ground.
Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.
Press the barbell overhead, fully extending your arms.
Lower the barbell back to shoulder height and repeat for the desired number of repetitions.', 'Usiądź na ławce, plecy wyprostuj, a stopy oprzyj płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.
Unieś sztangę do wysokości barków, utrzymując łokcie lekko ugięte i skierowane do przodu.
Wyciśnij sztangę nad głowę, w pełni prostując ręce.
Opuść sztangę z powrotem do wysokości barków i powtórz odpowiednią liczbę razy.', 'images/0087-0dCyly0.jpg', 'videos/0087-0dCyly0.gif'),
    ('gymvisual:0088', 'Barbell Seated Calf Raise', NULL, 'weight_reps', 'calves', ARRAY['hamstrings', 'quadriceps']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.
Place the balls of your feet on a raised platform, such as a block or step.
Position the barbell across your thighs and hold it securely with your hands.
Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.
Pause for a moment at the top, then slowly lower your heels back down to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, stopy oprzyj płasko na podłodze, a sztangę oprzyj na udach.
Ustaw palce stóp na podwyższonej platformie, na przykład klocku lub stopniu.
Umieść sztangę na udach i trzymaj ją pewnie rękami.
Utrzymując proste plecy i napięte mięśnie tułowia, unieś pięty z podłogi, prostując kostki.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść pięty z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0088-ktsFQAZ.jpg', 'videos/0088-ktsFQAZ.gif'),
    ('gymvisual:0089', 'Barbell Seated Close-Grip Concentration Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.
Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.
Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.
Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, stopy oprzyj płasko na podłodze, i chwyć sztangę chwytem podchwytem, dłonie na szerokość barków.
Oprzyj ramiona o wewnętrzną stronę ud, tuż nad kolanami, i pozwól sztandze zwisać przed sobą.
Utrzymując ramiona nieruchomo, wydychaj powietrze i uginaj sztangę w kierunku barków, napinając biceps.
Zatrzymaj się na chwilę w pozycji szczytowej, a następnie wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0089-1V1gj1u.jpg', 'videos/0089-1V1gj1u.gif'),
    ('gymvisual:0090', 'Barbell Seated Good Morning', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench', 'squat_rack']::TEXT[], 'intermediate', 'Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.
Keep your back straight and your chest up.
Slowly hinge forward at the hips, lowering your torso towards the ground.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, stopy oprzyj płasko na podłodze, a sztangę oprzyj na górnej części pleców.
Utrzymuj proste plecy i uniesioną klatkę piersiową.
Powoli pochylaj się do przodu w biodrach, opuszczając tułów w kierunku podłogi.
Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0090-d960PgE.jpg', 'videos/0090-d960PgE.gif'),
    ('gymvisual:0091', 'Barbell Seated Overhead Press', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your back straight and feet flat on the ground.
Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.
Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.
Press the barbell overhead by extending your arms fully.
Pause for a moment at the top, then slowly lower the barbell back to shoulder level.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, trzymając plecy proste, a stopy płasko na podłodze.
Chwyć sztangę chwytem nachwytem, nieco szerzej niż na szerokość barków.
Zdejmij sztangę ze stojaka i unieś ją na wysokość barków, zginając łokcie i kierując dłonie do przodu.
Wypchnij sztangę nad głowę, w pełni prostując ramiona.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść sztangę z powrotem na wysokość barków.
Powtórz zadaną liczbę powtórzeń.', 'images/0091-kTbSH9h.jpg', 'videos/0091-kTbSH9h.gif'),
    ('gymvisual:0092', 'Barbell Seated Overhead Triceps Extension', NULL, 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell', 'flat_bench']::TEXT[], 'intermediate', 'Sit on a bench with your back straight and feet flat on the ground.
Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.
Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.
Pause for a moment, then extend your arms to raise the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Usiądź na ławce, trzymając plecy proste, a stopy płasko na podłodze.
Chwyć sztangę chwytem nachwytem, z dłońmi rozstawionymi na szerokość barków, i unieś ją nad głowę.
Opuść sztangę za głowę, zginając łokcie i trzymając ramiona blisko głowy.
Zatrzymaj się na chwilę, a następnie wyprostuj ramiona, wracając ze sztangą do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0092-5uFK1xr.jpg', 'videos/0092-5uFK1xr.gif'),
    ('gymvisual:0094', 'Barbell Seated Twist', NULL, 'weight_reps', 'abs', ARRAY['lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Sit on a flat bench with your feet flat on the ground and your knees bent.
Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.
Engage your core and slowly twist your torso to one side, keeping your back straight.
Pause for a moment at the end of the twist, then slowly rotate back to the starting position.
Repeat the twist to the other side.
Continue alternating sides for the desired number of repetitions.', 'Usiądź na płaskiej ławce, trzymając stopy płasko na podłodze, a kolana ugięte.
Trzymaj sztangę obiema rękami przed klatką piersiową, z lekko ugiętymi łokciami.
Napnij mięśnie brzucha i powoli skręć tułów w jedną stronę, trzymając plecy proste.
Zatrzymaj się na chwilę na końcu skrętu, a następnie powoli wróć do pozycji wyjściowej.
Powtórz skręt w drugą stronę.
Kontynuuj naprzemienne skręty przez zadaną liczbę powtórzeń.', 'images/0094-dFSNDOA.jpg', 'videos/0094-dFSNDOA.gif'),
    ('gymvisual:0095', 'Barbell Shrug', 'Barbell Shrug', 'weight_reps', 'traps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.
Keep your arms straight and your back straight throughout the exercise.
Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.
Hold for a moment, then slowly lower your shoulders back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę przed sobą chwytem nachwytem.
Trzymaj ramiona proste, a plecy proste przez cały czas trwania ćwiczenia.
Unieś barki jak najwyżej w kierunku uszu, mocno napinając mięsień czworoboczny w górnej pozycji.
Przytrzymaj przez chwilę, a następnie powoli opuść barki z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0095-dG7tG5y.jpg', 'videos/0095-dG7tG5y.gif'),
    ('gymvisual:0096', 'Barbell Side Bent v. 2', NULL, 'weight_reps', 'abs', ARRAY['lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.
Keep your back straight and core engaged throughout the exercise.
Slowly bend your torso to the right side, lowering the barbell towards your right knee.
Pause for a moment, then return to the starting position.
Repeat the movement on the left side.
Continue alternating sides for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę obiema rękami, dłońmi skierowanymi w dół.
Trzymaj plecy proste, a mięśnie brzucha napięte przez cały czas trwania ćwiczenia.
Powoli pochyl tułów w prawą stronę, opuszczając sztangę w kierunku prawego kolana.
Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej.
Powtórz ruch w lewą stronę.
Kontynuuj naprzemienne pochylenia przez zadaną liczbę powtórzeń.', 'images/0096-i4JkUaL.jpg', 'videos/0096-i4JkUaL.gif'),
    ('gymvisual:0097', 'Barbell Side Split Squat v. 2', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.
Hold a barbell across your upper back, resting it on your shoulders.
Take a big step to the side with your right foot, keeping your left foot planted.
Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.
Push through your right heel to return to the starting position.
Repeat on the other side, stepping out with your left foot.
Continue alternating sides for the desired number of repetitions.', 'Stań ze stopami rozstawionymi szerzej niż barki, ze stopami skierowanymi lekko na zewnątrz.
Trzymaj sztangę na górnej części pleców, opierając ją na barkach.
Zrób duży krok w bok prawą stopą, trzymając lewą stopę nieruchomo na podłożu.
Ugnij prawe kolano i opuść ciało w przysiad, trzymając klatkę piersiową uniesioną, a plecy proste.
Wypchnij się przez prawą piętę, wracając do pozycji wyjściowej.
Powtórz w drugą stronę, wykonując krok lewą stopą.
Kontynuuj naprzemienne strony przez zadaną liczbę powtórzeń.', 'images/0097-HUEqZ1y.jpg', 'videos/0097-HUEqZ1y.gif'),
    ('gymvisual:0098', 'Barbell Side Split Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.
Hold a barbell across your upper back, resting it on your traps.
Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.
As you lower, push your knees out to the sides and keep your weight on your heels.
Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami rozstawionymi szerzej niż barki, ze stopami skierowanymi lekko na zewnątrz.
Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych.
Napnij mięśnie brzucha i trzymaj klatkę piersiową uniesioną, opuszczając ciało w przysiad, uginając kolana i biodra.
Podczas schodzenia w dół kieruj kolana na zewnątrz i trzymaj ciężar na piętach.
Zejdź, aż uda będą równoległe do podłoża, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0098-W31mMjd.jpg', 'videos/0098-W31mMjd.gif'),
    ('gymvisual:0099', 'Barbell Single Leg Split Squat', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, holding a barbell across your upper back.
Take a large step forward with one leg, keeping your torso upright.
Lower your body by bending your front knee and hip, while keeping your back leg straight.
Continue lowering until your front thigh is parallel to the ground.
Pause for a moment, then push through your front heel to return to the starting position.
Repeat for the desired number of repetitions, then switch legs.', 'Stań ze stopami na szerokość barków, trzymając sztangę na górnej części pleców.
Zrób duży krok do przodu jedną nogą, trzymając tułów w pionie.
Opuść ciało, uginając przednie kolano i biodro, trzymając tylną nogę wyprostowaną.
Kontynuuj opuszczanie, aż przednie udo będzie równoległe do podłoża.
Zatrzymaj się na chwilę, a następnie wypchnij się przez przednią piętę, wracając do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń, a następnie zmień nogę.', 'images/0099-gGNQmVt.jpg', 'videos/0099-gGNQmVt.gif'),
    ('gymvisual:0100', 'Barbell Skier', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'abs']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.
Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.
Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.
As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę przed udami chwytem nachwytem.
Ugnij lekko kolana i pochyl tułów do przodu w biodrach, trzymając plecy proste, a klatkę piersiową uniesioną.
Jednocześnie unieś sztangę w kierunku barków, lekko podskakując.
Gdy osiągniesz szczyt ruchu, szybko odwróć kierunek i opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0100-4Leypho.jpg', 'videos/0100-4Leypho.gif'),
    ('gymvisual:0101', 'Barbell Speed Squat', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, toes slightly turned out.
Hold the barbell across your upper back, resting it on your traps or rear delts.
Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.
Lower until your thighs are parallel to the ground, or as low as you can comfortably go.
Drive through your heels to stand back up, squeezing your glutes at the top.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, ze stopami lekko skierowanymi na zewnątrz.
Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.
Napnij mięśnie brzucha i trzymaj klatkę piersiową uniesioną, cofając biodra i opuszczając je w dół, jakbyś siadał na krześle.
Zejdź, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Wypchnij się przez pięty, wracając do pozycji stojącej, napinając pośladki w górnej pozycji.
Powtórz zadaną liczbę powtórzeń.', 'images/0101-euI1BwR.jpg', 'videos/0101-euI1BwR.gif'),
    ('gymvisual:0102', 'Barbell Squat (on Knees)', NULL, 'weight_reps', 'quadriceps', ARRAY['glutes', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.
Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.
Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.
Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
Pause for a moment at the bottom, then push through your heels to return to the starting position.
Repeat for the desired number of repetitions.', 'Zacznij, klęcząc na podłodze, z kolanami rozstawionymi na szerokość bioder, a palcami stóp skierowanymi do przodu.
Umieść sztangę na barkach, chwytając ją nachwytem, z dłońmi nieco szerzej niż na szerokość barków.
Napnij mięśnie brzucha i trzymaj klatkę piersiową uniesioną, powoli opuszczając ciało poprzez zginanie kolan, trzymając plecy proste.
Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.
Zatrzymaj się na chwilę w dolnej pozycji, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0102-oR7O9LW.jpg', 'videos/0102-oR7O9LW.gif'),
    ('gymvisual:0103', 'Barbell Standing Ab Rollerout', NULL, 'weight_reps', 'abs', ARRAY['shoulders', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.
Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.
Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.
Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.
Repeat for the desired number of repetitions.', 'Stań w pozycji wyprostowanej, ze stopami na szerokość barków, trzymając sztangę obiema rękami przed udami.
Napnij mięśnie brzucha i powoli tocz sztangę w kierunku podłogi, trzymając plecy proste, a ramiona wyprostowane.
Kontynuuj toczenie sztangi do przodu, aż ciało będzie w pełni wyprostowane, a dłonie znajdą się bezpośrednio nad głową.
Zatrzymaj się na chwilę, a następnie powoli tocz sztangę z powrotem w kierunku ud, zachowując kontrolę i napięte mięśnie brzucha.
Powtórz zadaną liczbę powtórzeń.', 'images/0103-xnInPfE.jpg', 'videos/0103-xnInPfE.gif'),
    ('gymvisual:0104', 'Barbell Standing Back Wrist Curl', NULL, 'weight_reps', 'forearms', ARRAY['biceps', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.
Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.
Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.
Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań wyprostowany, ze stopami na szerokość barków, trzymając sztangę chwytem nachwytem.
Oprzyj sztangę na grzbietach dłoni, z dłońmi skierowanymi w dół, a palcami skierowanymi w stronę ciała.
Trzymając przedramiona nieruchomo, wydychaj powietrze i unieś nadgarstki jak najwyżej.
Przytrzymaj napiętą pozycję przez krótką chwilę, a następnie wdychaj powietrze i powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0104-2qTvJAZ.jpg', 'videos/0104-2qTvJAZ.gif'),
    ('gymvisual:0105', 'Barbell Standing Bradford Press', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.
Press the barbell overhead, fully extending your arms.
Lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę przed barkami chwytem nachwytem.
Wypchnij sztangę nad głowę, w pełni prostując ramiona.
Opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0105-dCPESfR.jpg', 'videos/0105-dCPESfR.gif'),
    ('gymvisual:0106', 'Barbell Standing Close Grip Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.
Keep your elbows close to your torso and your upper arms stationary throughout the movement.
Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale as you slowly begin to bring the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań wyprostowany, ze stopami na szerokość barków, trzymając sztangę chwytem podchwytem, z dłońmi blisko siebie.
Trzymaj łokcie blisko tułowia, a ramiona nieruchomo przez cały czas trwania ruchu.
Wydychaj powietrze, uginając ramiona i napinając mięśnie dwugłowe ramienia. Kontynuuj unoszenie sztangi, aż mięśnie dwugłowe będą w pełni napięte, a sztanga znajdzie się na wysokości barków.
Przytrzymaj napiętą pozycję przez krótką chwilę, mocno napinając mięśnie dwugłowe.
Wdychaj powietrze, powoli wracając ze sztangą do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0106-4dUn2iv.jpg', 'videos/0106-4dUn2iv.gif'),
    ('gymvisual:0107', 'Barbell Standing Front Raise Over Head', NULL, 'weight_reps', 'shoulders', ARRAY['triceps', 'upper_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.
Keep your back straight and engage your core.
Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.
Continue lifting until the barbell is slightly above shoulder level.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę przed udami chwytem nachwytem.
Trzymaj plecy proste i napnij mięśnie brzucha.
Powoli unieś sztangę przed sobą, trzymając ramiona proste, a dłonie skierowane w dół.
Kontynuuj unoszenie, aż sztanga znajdzie się nieco powyżej poziomu barków.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0107-S8mo30S.jpg', 'videos/0107-S8mo30S.gif'),
    ('gymvisual:0108', 'Barbell Standing Leg Calf Raise', NULL, 'weight_reps', 'calves', ARRAY['hamstrings', 'glutes']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and place a barbell across your upper back.
Raise your heels off the ground as high as possible, using your calves.
Pause for a moment at the top, then slowly lower your heels back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków i umieść sztangę na górnej części pleców.
Unieś pięty nad podłogę jak najwyżej, korzystając z mięśni łydek.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść pięty z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0108-rGwhJ5o.jpg', 'videos/0108-rGwhJ5o.gif'),
    ('gymvisual:0109', 'Barbell Standing Overhead Triceps Extension', NULL, 'weight_reps', 'triceps', ARRAY['shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.
Raise the barbell overhead, fully extending your arms.
Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.
Pause for a moment, then raise the barbell back to the starting position by extending your arms.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę chwytem nachwytem.
Unieś sztangę nad głowę, w pełni prostując ramiona.
Trzymając ramiona blisko głowy, powoli opuść sztangę za głowę, uginając łokcie.
Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej, prostując ramiona.
Powtórz zadaną liczbę powtórzeń.', 'images/0109-dZl9Q27.jpg', 'videos/0109-dZl9Q27.gif'),
    ('gymvisual:0110', 'Barbell Standing Reverse Grip Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.
Keep your elbows close to your torso and your upper arms stationary.
Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale and slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań wyprostowany, ze stopami na szerokość barków, trzymając sztangę chwytem podchwytem, dłońmi skierowanymi do góry.
Trzymaj łokcie blisko tułowia, a ramiona nieruchomo.
Wydychaj powietrze i unieś sztangę, napinając mięśnie dwugłowe, przybliżając ją jak najbliżej barków.
Przytrzymaj napiętą pozycję przez krótką chwilę, mocno napinając mięśnie dwugłowe.
Wdychaj powietrze i powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0110-LWuA3aZ.jpg', 'videos/0110-LWuA3aZ.gif'),
    ('gymvisual:0111', 'Barbell Standing Rocking Leg Calf Raise', NULL, 'weight_reps', 'calves', ARRAY['hamstrings', 'quadriceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell across your upper back.
Raise your heels off the ground as high as possible, balancing on the balls of your feet.
Slowly lower your heels back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę na górnej części pleców.
Unieś pięty nad podłogę jak najwyżej, balansując na palcach stóp.
Powoli opuść pięty z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0111-6HiHHe0.jpg', 'videos/0111-6HiHHe0.gif'),
    ('gymvisual:0112', 'Barbell Standing Twist', NULL, 'weight_reps', 'abs', ARRAY['lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.
Engage your core and keep your back straight throughout the exercise.
Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.
Pause for a moment at the end of the twist, then slowly return to the starting position.
Repeat the twist to the left side.
Continue alternating twists for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę przed klatką piersiową obiema rękami, dłońmi skierowanymi w dół.
Napnij mięśnie brzucha i trzymaj plecy proste przez cały czas trwania ćwiczenia.
Powoli skręć tułów w prawą stronę, obracając się na stopach i biodrach, jednocześnie utrzymując stabilność dolnej części ciała.
Zatrzymaj się na chwilę na końcu skrętu, a następnie powoli wróć do pozycji wyjściowej.
Powtórz skręt w lewą stronę.
Kontynuuj naprzemienne skręty przez zadaną liczbę powtórzeń.', 'images/0112-yQe5HpE.jpg', 'videos/0112-yQe5HpE.gif'),
    ('gymvisual:0113', 'Barbell Standing Wide-Grip Curl', NULL, 'weight_reps', 'biceps', ARRAY['forearms', 'shoulders']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.
Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.
Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.
Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.
Hold the contracted position for a brief pause as you squeeze your biceps.
Inhale and slowly begin to lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań wyprostowany, ze stopami na szerokość barków, trzymając sztangę chwytem nachwytem, z dłońmi szerzej niż na szerokość barków.
Trzymaj sztangę na wyprostowanych ramionach przed udami, dłońmi skierowanymi od ciała.
Trzymając ramiona nieruchomo, wydychaj powietrze i unieś sztangę do góry, napinając mięśnie dwugłowe.
Kontynuuj unoszenie sztangi, aż mięśnie dwugłowe będą w pełni napięte, a sztanga znajdzie się na wysokości barków.
Przytrzymaj napiętą pozycję przez krótką chwilę, mocno napinając mięśnie dwugłowe.
Wdychaj powietrze i powoli zacznij opuszczać sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0113-NdIb5Z1.jpg', 'videos/0113-NdIb5Z1.gif'),
    ('gymvisual:0114', 'Barbell Step-Up', NULL, 'weight_reps', 'glutes', ARRAY['quadriceps', 'hamstrings', 'calves']::TEXT[], 'barbell', ARRAY['barbell', 'plyo_box']::TEXT[], 'intermediate', 'Stand in front of a bench or step with a barbell resting on your upper back.
Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.
Push through your heel and step up onto the bench or step, fully extending your hip and knee.
Pause briefly at the top, then lower yourself back down to the starting position.
Repeat with the opposite leg.
Continue alternating legs for the desired number of repetitions.', 'Stań przed ławką lub stopniem, ze sztangą opartą na górnej części pleców.
Postaw jedną stopę na ławce lub stopniu, upewniając się, że cała stopa jest w kontakcie z powierzchnią.
Wypchnij się przez piętę i wejdź na ławkę lub stopień, w pełni prostując biodro i kolano.
Zatrzymaj się na chwilę w górnej pozycji, a następnie opuść się z powrotem do pozycji wyjściowej.
Powtórz przeciwną nogą.
Kontynuuj naprzemienne nogi przez zadaną liczbę powtórzeń.', 'images/0114-Kxquu2E.jpg', 'videos/0114-Kxquu2E.gif'),
    ('gymvisual:0115', 'Barbell Stiff Leg Good Morning', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell', 'squat_rack']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and your knees slightly bent.
Hold the barbell across your upper back, resting it on your traps.
Keeping your back straight, hinge forward at the hips, pushing your glutes back.
Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
Engage your glutes and hamstrings to return to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, a kolana lekko ugięte.
Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych.
Trzymając plecy proste, pochyl tułów do przodu w biodrach, cofając pośladki.
Opuść tułów, aż będzie równoległy do podłoża, czując rozciąganie mięśni dwugłowych uda.
Napnij pośladki i mięśnie dwugłowe uda, wracając do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0115-JrOHAZc.jpg', 'videos/0115-JrOHAZc.gif'),
    ('gymvisual:0116', 'Barbell Straight Leg Deadlift', NULL, 'weight_reps', 'hamstrings', ARRAY['glutes', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and your toes pointing forward.
Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.
Lower the barbell until you feel a stretch in your hamstrings.
Engage your hamstrings and glutes to lift the barbell back up to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, a palcami stóp skierowanymi do przodu.
Trzymaj sztangę chwytem nachwytem, z dłońmi nieco szerzej niż na szerokość barków.
Zegnij się w biodrach i opuść sztangę w kierunku podłogi, trzymając plecy proste, a kolana lekko ugięte.
Opuść sztangę, aż poczujesz rozciąganie mięśni dwugłowych uda.
Napnij mięśnie dwugłowe uda i pośladki, unosząc sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0116-hrVQWvE.jpg', 'videos/0116-hrVQWvE.gif'),
    ('gymvisual:0117', 'Barbell Sumo Deadlift', NULL, 'weight_reps', 'glutes', ARRAY['hamstrings', 'quadriceps', 'lower_back']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet wider than shoulder-width apart, toes pointing outwards.
Place a barbell on the ground in front of you, centered between your feet.
Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.
Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.
As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.
Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.
Repeat for the desired number of repetitions.', 'Stań ze stopami rozstawionymi szerzej niż barki, ze stopami skierowanymi na zewnątrz.
Umieść sztangę na podłodze przed sobą, na środku między stopami.
Ugnij kolana i opuść biodra, trzymając plecy proste, a klatkę piersiową uniesioną, aby chwycić sztangę chwytem nachwytem.
Napnij mięśnie brzucha i wypchnij się przez pięty, unosząc sztangę z podłogi, jednocześnie prostując biodra i kolana.
Podczas unoszenia trzymaj klatkę piersiową uniesioną, a plecy proste, i przesuwaj biodra do przodu, aby w pełni zaangażować pośladki.
Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej, zachowując kontrolę przez cały czas trwania ruchu.
Powtórz zadaną liczbę powtórzeń.', 'images/0117-KgI0tqW.jpg', 'videos/0117-KgI0tqW.gif'),
    ('gymvisual:0118', 'Barbell Reverse Grip Bent Over Row', NULL, 'weight_reps', 'upper_back', ARRAY['biceps', 'forearms']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and knees slightly bent.
Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.
Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.
Pull the barbell towards your lower chest, squeezing your shoulder blades together.
Pause for a moment at the top, then slowly lower the barbell back to the starting position.
Repeat for the desired number of repetitions.', 'Stań w rozkroku na szerokość barków, kolana lekko ugięte.
Chwyć sztangę chwytem nachwytem, dłonie skierowane w dół, nieco szerzej niż szerokość barków.
Pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową, aż tułów będzie niemal równoległy do podłogi.
Przyciągnij sztangę w kierunku dolnej części klatki piersiowej, ściskając łopatki.
Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz odpowiednią liczbę razy.', 'images/0118-SzX3uzM.jpg', 'videos/0118-SzX3uzM.gif'),
    ('gymvisual:0119', 'Barbell Upright Row v. 2', NULL, 'weight_reps', 'shoulders', ARRAY['traps', 'biceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Let the barbell hang in front of your thighs, arms fully extended.
Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.
Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę chwytem nachwytem, z dłońmi nieco szerzej niż na szerokość barków.
Pozwól sztandze zwisać przed udami, z ramionami w pełni wyprostowanymi.
Trzymając plecy proste, wydychaj powietrze i unieś sztangę prosto w górę w kierunku brody, prowadząc ruch łokciami.
Zatrzymaj się na chwilę w górnej pozycji, a następnie wdychaj powietrze i powoli opuść sztangę z powrotem do pozycji wyjściowej.
Powtórz zadaną liczbę powtórzeń.', 'images/0119-83HoW9X.jpg', 'videos/0119-83HoW9X.gif'),
    ('gymvisual:0120', 'Barbell Upright Row', NULL, 'weight_reps', 'shoulders', ARRAY['traps', 'biceps']::TEXT[], 'barbell', ARRAY['barbell']::TEXT[], 'intermediate', 'Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.
Let the barbell hang in front of your thighs, arms fully extended.
Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.
Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.
Repeat for the desired number of repetitions.', 'Stań ze stopami na szerokość barków, trzymając sztangę chwytem nachwytem, z dłońmi nieco szerzej niż na szerokość barków.
Pozwól sztandze zwisać przed udami, z ramionami w pełni wyprostowanymi.
